const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const safeWorkflow = String(workflow.name ?? 'Job Monitor').slice(0, 120);
const safeExecution = String(execution.id ?? 'unknown').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
const safeNode = String(execution.lastNodeExecuted ?? 'unknown').replace(/[\r\n\t]/g, ' ').slice(0, 120);

return [{
  json: {
    delivery_mode: 'preview_only',
    message: [
      'Job monitor failed',
      `Workflow: ${safeWorkflow}`,
      `Execution: ${safeExecution}`,
      `Last node: ${safeNode}`,
      'Inspect the private n8n execution log. Error details are intentionally omitted from this alert.'
    ].join('\n')
  }
}];
